import{c as e,Q as i,j as a,m as n}from"./chunks/framework.W-g_WCNV.js";const p=JSON.parse('{"title":"Invite links","description":"","frontmatter":{},"headers":[],"relativePath":"admin/invites.md","filePath":"admin/invites.md"}'),r={name:"admin/invites.md"};function d(s,t,o,l,h,c){return i(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="invite-links" tabindex="-1">Invite links <a class="header-anchor" href="#invite-links" aria-label="Permalink to &quot;Invite links&quot;">​</a></h1><p>Invite links let you onboard specific people without opening registration to everyone. Each link is single-use and expires after the period you choose when creating it.</p><h2 id="creating-an-invite" tabindex="-1">Creating an invite <a class="header-anchor" href="#creating-an-invite" aria-label="Permalink to &quot;Creating an invite&quot;">​</a></h2><p>Go to <strong>Admin - Invites</strong> and click <strong>New invite</strong>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td>Email address</td><td>No</td><td>Pre-fills the registration form with this address and prevents the user from changing it. Leave blank to allow any email.</td></tr><tr><td>Note</td><td>No</td><td>Internal reminder for yourself - not shown to the invitee.</td></tr><tr><td>Expires after</td><td>Yes</td><td>How long the link stays valid. Choices are 1, 3, 7, 14, or 30 days. Default is 7 days.</td></tr></tbody></table><p>After clicking <strong>Create invite</strong>, the generated link appears at the top of the page. Copy it and share it with the person you want to invite. The raw token is only shown once - GateKeeper stores only a hash and cannot display it again.</p><h2 id="what-the-invitee-sees" tabindex="-1">What the invitee sees <a class="header-anchor" href="#what-the-invitee-sees" aria-label="Permalink to &quot;What the invitee sees&quot;">​</a></h2><p>Opening the link takes the user to <code>/register?invite=&lt;token&gt;</code>. They see a form with:</p><ul><li><strong>Email</strong> - pre-filled and locked if you specified an address, or editable if you left it blank.</li><li><strong>Password</strong> and <strong>Confirm password</strong> - must be at least 8 characters.</li></ul><p>On successful registration, the account is created immediately and the user is signed in. The invite link is then marked as used and cannot be reused.</p><h2 id="invite-statuses" tabindex="-1">Invite statuses <a class="header-anchor" href="#invite-statuses" aria-label="Permalink to &quot;Invite statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Active</td><td>Valid and unused, can still be opened.</td></tr><tr><td>Used</td><td>Registration was completed.</td></tr><tr><td>Expired</td><td>The expiry time passed before anyone used it.</td></tr></tbody></table><h2 id="revoking-an-invite" tabindex="-1">Revoking an invite <a class="header-anchor" href="#revoking-an-invite" aria-label="Permalink to &quot;Revoking an invite&quot;">​</a></h2><p>Click the trash icon next to any active invite to revoke it. The link will stop working immediately. Used and expired invites are kept for audit purposes but cannot be revoked (they are already inactive).</p><h2 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h2><p>Every invite action is recorded:</p><table tabindex="0"><thead><tr><th>Event</th><th>When</th></tr></thead><tbody><tr><td><code>invite.created</code></td><td>An admin generated an invite.</td></tr><tr><td><code>invite.used</code></td><td>A user registered with the link.</td></tr><tr><td><code>invite.revoked</code></td><td>An admin deleted an invite.</td></tr></tbody></table>',17)])])}const u=e(r,[["render",d]]);export{p as __pageData,u as default};
